class SimpleLru<K, V>(private val cap: Int) {
    private val map = object : LinkedHashMap<K, V>(cap, 0.75f, false) {
        override fun removeEldestEntry(e: MutableMap.MutableEntry<K, V>?) = size > cap
    }
    fun get(k: K) = map[k]
    fun put(k: K, v: V) { map[k] = v }
}

